/*
 * Golden vectors (SPEC §14): every tests/vectors/core/*.json file runs through the public
 * API and is compared with the rules of §14 — decimal strings exactly, rates within
 * max(1e−7, 1e−9·|v|) percentage points with equal display and precision, warnings and
 * errors as sets. The vectors are generated by the independent reference implementation
 * and never edited by hand.
 */

import { describe, expect, it } from 'vitest';
import {
  type LoanResult,
  type RateFailure,
  type RateMetric,
  calculateLoan,
  checkInvariants,
  computeRateMetrics,
  minorUnits,
} from './index';

interface ExpectedRate {
  readonly value?: string;
  readonly display?: string;
  readonly precision?: number;
  readonly warnings?: readonly string[];
  readonly ok?: false;
  readonly reason?: string;
}

interface Vector {
  readonly schemaVersion: number;
  readonly id: string;
  readonly kind: 'loan' | 'cashflows';
  readonly input: unknown;
  readonly expected: {
    readonly ok: boolean;
    readonly errors?: readonly { readonly code: string; readonly field: string | null }[];
    readonly warnings?: readonly { readonly code: string }[];
    readonly summary?: Readonly<Record<string, unknown>>;
    readonly rates?: Readonly<Record<string, ExpectedRate>>;
    readonly rows?: readonly Readonly<Record<string, unknown>>[];
  };
}

const FILES = import.meta.glob<unknown>('../../tests/vectors/core/*.json', {
  eager: true,
  import: 'default',
});

/** Narrows a parsed vector file to the fields the harness reads. */
function isVector(value: unknown): value is Vector {
  return (
    typeof value === 'object' &&
    value !== null &&
    'id' in value &&
    'kind' in value &&
    'input' in value &&
    'expected' in value
  );
}

const VECTORS: readonly Vector[] = Object.entries(FILES)
  .map(([path, value]) => {
    if (!isVector(value)) {
      throw new Error(`${path} is not a golden vector`);
    }
    return value;
  })
  .sort((a, b) => a.id.localeCompare(b.id));

/** `{ code, field }` pairs as sorted keys, so error lists compare as sets. */
function errorKeys(errors: readonly { code: string; field: string | null }[]): string[] {
  return errors.map((error) => `${error.code}@${String(error.field)}`).sort();
}

function isFailure(rate: RateMetric | RateFailure): rate is RateFailure {
  return 'ok' in rate;
}

/** SPEC §14 rate comparison; returns a list of mismatches (empty when it matches). */
function compareRates(
  actual: Readonly<Record<string, RateMetric | RateFailure | undefined>>,
  expected: Readonly<Record<string, ExpectedRate>>,
): string[] {
  const problems: string[] = [];
  for (const [method, want] of Object.entries(expected)) {
    const got = actual[method];
    if (got === undefined) {
      problems.push(`${method}: missing`);
      continue;
    }
    if (want.ok === false) {
      if (!isFailure(got) || got.reason !== want.reason) {
        problems.push(
          `${method}: expected failure ${String(want.reason)}, got ${JSON.stringify(got)}`,
        );
      }
      continue;
    }
    if (isFailure(got)) {
      problems.push(`${method}: expected a value, got failure ${got.reason}`);
      continue;
    }
    const value = Number(want.value);
    const tolerance = Math.max(1e-7, 1e-9 * Math.abs(value));
    if (!(Math.abs(got.value - value) <= tolerance)) {
      problems.push(
        `${method}: value ${String(got.value)} vs ${String(want.value)} (tolerance ${String(tolerance)})`,
      );
    }
    if (got.display !== want.display || got.precision !== want.precision) {
      problems.push(
        `${method}: display ${got.display}/${String(got.precision)} vs ${String(want.display)}/${String(want.precision)}`,
      );
    }
    const gotWarnings = [...(got.warnings ?? [])].sort();
    const wantWarnings = [...(want.warnings ?? [])].sort();
    if (JSON.stringify(gotWarnings) !== JSON.stringify(wantWarnings)) {
      problems.push(
        `${method}: warnings ${JSON.stringify(gotWarnings)} vs ${JSON.stringify(wantWarnings)}`,
      );
    }
  }
  return problems;
}

/** Fields present in `expected` compared exactly; `null` matches `null` or absent. */
function compareFields(
  label: string,
  actual: Readonly<Record<string, unknown>>,
  expected: Readonly<Record<string, unknown>>,
): string[] {
  const problems: string[] = [];
  for (const [field, want] of Object.entries(expected)) {
    const got = actual[field];
    if (want === null ? got !== null && got !== undefined : got !== want) {
      problems.push(`${label}.${field}: ${JSON.stringify(got)} vs ${JSON.stringify(want)}`);
    }
  }
  return problems;
}

function checkLoan(vector: Vector, result: LoanResult): void {
  const { expected } = vector;
  if (!expected.ok) {
    expect(result.ok).toBe(false);
    if (!result.ok) {
      expect(errorKeys(result.errors)).toEqual(errorKeys(expected.errors ?? []));
    }
    return;
  }
  if (!result.ok) {
    throw new Error(`expected a schedule, got errors ${JSON.stringify(result.errors)}`);
  }
  expect(result.warnings.map((warning) => warning.code).sort()).toEqual(
    (expected.warnings ?? []).map((warning) => warning.code).sort(),
  );
  const problems = [
    ...compareFields(
      'summary',
      result.summary as unknown as Record<string, unknown>,
      expected.summary ?? {},
    ),
    ...compareRates(result.rates, expected.rates ?? {}),
  ];
  const rows = expected.rows ?? [];
  if (result.rows.length !== rows.length) {
    problems.push(`rows: ${String(result.rows.length)} vs ${String(rows.length)}`);
  }
  rows.forEach((row, index) => {
    const got = result.rows[index];
    if (got !== undefined) {
      problems.push(
        ...compareFields(`rows[${String(index)}]`, got as unknown as Record<string, unknown>, row),
      );
    }
  });
  expect(problems).toEqual([]);
  // Beyond §14: the vector's rates are exactly the requested metrics, and I1–I9 hold.
  expect(Object.keys(result.rates).sort()).toEqual(Object.keys(expected.rates ?? {}).sort());
  const input = vector.input as {
    currency: string;
    repayment: 'annuity' | 'equal-principal' | 'bullet' | 'balloon';
  };
  expect(
    checkInvariants(result, {
      minorUnits: minorUnits(input.currency) ?? 2,
      repayment: input.repayment,
    }),
  ).toEqual([]);
}

describe('golden vectors (tests/vectors/core)', () => {
  it('finds the vector files', () => {
    expect(VECTORS.length).toBeGreaterThanOrEqual(106);
    expect(new Set(VECTORS.map((vector) => vector.id)).size).toBe(VECTORS.length);
    expect(VECTORS.every((vector) => vector.schemaVersion === 1)).toBe(true);
  });

  it.each(VECTORS.map((vector) => [vector.id, vector] as const))('%s', (_id, vector) => {
    if (vector.kind === 'loan') {
      checkLoan(vector, calculateLoan(vector.input));
      return;
    }
    const result = computeRateMetrics(vector.input);
    const { expected } = vector;
    if (!expected.ok) {
      expect(result.ok).toBe(false);
      if (!result.ok) {
        expect(errorKeys(result.errors)).toEqual(errorKeys(expected.errors ?? []));
      }
      return;
    }
    if (!result.ok) {
      throw new Error(`expected rates, got errors ${JSON.stringify(result.errors)}`);
    }
    expect(compareRates(result.rates, expected.rates ?? {})).toEqual([]);
    expect(Object.keys(result.rates).sort()).toEqual(Object.keys(expected.rates ?? {}).sort());
  });
});
